import{_ as a,m as t,k as o,ah as n}from"./chunks/framework.HEc25T99.js";const p=JSON.parse('{"title":"FAQ","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"developers/resources/faq.md","filePath":"src/en/developers/resources/faq.md"}'),s={name:"developers/resources/faq.md"};function i(r,e,d,c,l,h){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>Common questions about developing Creopse templates. For anything not covered here, browse the rest of the <a href="./../getting-started/introduction.html">developer documentation</a> or <a href="https://github.com/creopse/creopse/issues" target="_blank" rel="noreferrer">report a bug</a>.</p><h2 id="sections-widgets" tabindex="-1">Sections &amp; Widgets <a class="header-anchor" href="#sections-widgets" aria-label="Permalink to &quot;Sections &amp; Widgets&quot;">​</a></h2><h3 id="my-cta-button-doesn-t-lead-anywhere-why" tabindex="-1">My CTA button doesn&#39;t lead anywhere, why? <a class="header-anchor" href="#my-cta-button-doesn-t-lead-anywhere-why" aria-label="Permalink to &quot;My CTA button doesn&#39;t lead anywhere, why?&quot;">​</a></h3><p>If the field is of type <code>menu-item-link</code>, the <code>href</code> must be resolved through <code>getLinkFromMenuItemId(field)</code> and navigation handled through <code>openLink(field)</code> — never a raw <code>href</code> on the field&#39;s value. See <a href="./../development/sections-widgets.html#links-and-cta-buttons">Links and CTA buttons</a>.</p><h3 id="my-scaffolded-header-footer-shows-no-navigation-links" tabindex="-1">My scaffolded Header/Footer shows no navigation links <a class="header-anchor" href="#my-scaffolded-header-footer-shows-no-navigation-links" aria-label="Permalink to &quot;My scaffolded Header/Footer shows no navigation links&quot;">​</a></h3><p>A Header/Footer component only displays the items returned by <code>getMenuItemsByLocation(&#39;header&#39;|&#39;footer&#39;)</code> — if no location, menu, or item has been created in the database yet, the list is naturally empty. See <a href="./../development/menus.html">Menus</a>.</p><h3 id="why-doesn-t-the-source-template-s-carousel-modal-accordion-work-anymore-once-integrated" tabindex="-1">Why doesn&#39;t the source template&#39;s carousel/modal/accordion work anymore once integrated? <a class="header-anchor" href="#why-doesn-t-the-source-template-s-carousel-modal-accordion-work-anymore-once-integrated" aria-label="Permalink to &quot;Why doesn&#39;t the source template&#39;s carousel/modal/accordion work anymore once integrated?&quot;">​</a></h3><p>No plugin JS script (Bootstrap, lightbox...) should remain functional in a final component — these behaviors are reimplemented natively (Vue/React). The <code>data-bs-toggle</code> attribute can stay for CSS styling, but no longer drives the behavior. See <a href="./../development/sections-widgets.html#interactive-behaviors">Interactive behaviors</a>.</p><h3 id="how-do-i-choose-between-text-i18n-text-and-i18n-editor-for-a-field" tabindex="-1">How do I choose between <code>text</code>, <code>i18n-text</code>, and <code>i18n-editor</code> for a field? <a class="header-anchor" href="#how-do-i-choose-between-text-i18n-text-and-i18n-editor-for-a-field" aria-label="Permalink to &quot;How do I choose between `text`, `i18n-text`, and `i18n-editor` for a field?&quot;">​</a></h3><p><code>text</code> for anything non-translatable (URL, proper name); <code>i18n-text</code> for a short translatable string (title, label); <code>i18n-editor</code> for any description, regardless of length — never <code>i18n-textarea</code>. See <a href="./../development/sections-widgets.html#field-types">Field types</a>.</p><h3 id="can-the-same-section-appear-twice-on-a-page-with-different-content" tabindex="-1">Can the same section appear twice on a page with different content? <a class="header-anchor" href="#can-the-same-section-appear-twice-on-a-page-with-different-content" aria-label="Permalink to &quot;Can the same section appear twice on a page with different content?&quot;">​</a></h3><p>Yes, using a distinct <code>--link-id</code> on each attachment (<code>creopse page attach-section home Hero --link-id top</code>, <code>--link-id bottom</code>...). See <a href="./../development/pages.html#attaching-sections">Attaching sections</a>.</p><h2 id="content-models-permalinks" tabindex="-1">Content models &amp; permalinks <a class="header-anchor" href="#content-models-permalinks" aria-label="Permalink to &quot;Content models &amp; permalinks&quot;">​</a></h2><h3 id="when-should-i-use-a-content-model-instead-of-a-section-collection" tabindex="-1">When should I use a content model instead of a section collection? <a class="header-anchor" href="#when-should-i-use-a-content-model-instead-of-a-section-collection" aria-label="Permalink to &quot;When should I use a content model instead of a section collection?&quot;">​</a></h3><p>As soon as content follows a &quot;list + detail&quot; pattern (each element has its own detail page) — Services, Projects, Team... A plain section collection is enough for content that&#39;s always displayed as a block on the same page. See <a href="./../development/content-models.html#when-to-use-a-content-model">When to use a content model</a>.</p><h3 id="i-set-has-permalink-true-on-my-model-but-the-detail-page-returns-a-404" tabindex="-1">I set <code>--has-permalink true</code> on my model but the detail page returns a 404 <a class="header-anchor" href="#i-set-has-permalink-true-on-my-model-but-the-detail-page-returns-a-404" aria-label="Permalink to &quot;I set `--has-permalink true` on my model but the detail page returns a 404&quot;">​</a></h3><p>That flag only marks the model as eligible — it wires no route. The permalink needs to be created separately with <code>creopse permalink add</code>. See <a href="./../development/permalinks.html">Permalinks</a>.</p><h3 id="how-do-i-choose-between-resolving-a-permalink-by-id-or-by-slug" tabindex="-1">How do I choose between resolving a permalink by <code>id</code> or by <code>slug</code>? <a class="header-anchor" href="#how-do-i-choose-between-resolving-a-permalink-by-id-or-by-slug" aria-label="Permalink to &quot;How do I choose between resolving a permalink by `id` or by `slug`?&quot;">​</a></h3><p><code>id</code> by default for a custom content model, unless a dedicated field (e.g. <code>slug</code>) actually exists in its structure. For news articles/categories/tags (native structure), <code>slug</code> is the idiomatic choice. See <a href="./../development/permalinks.html#choosing-content-param">Permalinks</a>.</p><h2 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to &quot;Pages&quot;">​</a></h2><h3 id="how-do-i-keep-a-footer-or-header-strictly-identical-across-all-pages" tabindex="-1">How do I keep a Footer (or Header) strictly identical across all pages? <a class="header-anchor" href="#how-do-i-keep-a-footer-or-header-strictly-identical-across-all-pages" aria-label="Permalink to &quot;How do I keep a Footer (or Header) strictly identical across all pages?&quot;">​</a></h3><p>With <code>creopse page set-section-source</code>, which points one section instance to another&#39;s data source — rather than manually duplicating the same data on every page. See <a href="./../development/pages.html#sharing-data-across-pages">Sharing data across pages</a>.</p><h3 id="what-s-the-difference-between-disabling-a-section-and-detaching-it" tabindex="-1">What&#39;s the difference between disabling a section and detaching it? <a class="header-anchor" href="#what-s-the-difference-between-disabling-a-section-and-detaching-it" aria-label="Permalink to &quot;What&#39;s the difference between disabling a section and detaching it?&quot;">​</a></h3><p><code>toggle-section-status</code> disables an instance without removing it (useful for a section that&#39;s ready but not yet meant to be published); <code>detach-section</code> removes it permanently — reserve this for attachment mistakes. See <a href="./../development/pages.html#enabling-disabling-or-detaching-an-instance">Pages</a>.</p><h2 id="vue-vs-react" tabindex="-1">Vue vs React <a class="header-anchor" href="#vue-vs-react" aria-label="Permalink to &quot;Vue vs React&quot;">​</a></h2><h3 id="how-do-i-choose-between-vue-and-react-and-can-i-switch-later" tabindex="-1">How do I choose between Vue and React, and can I switch later? <a class="header-anchor" href="#how-do-i-choose-between-vue-and-react-and-can-i-switch-later" aria-label="Permalink to &quot;How do I choose between Vue and React, and can I switch later?&quot;">​</a></h3><p>The choice is made at install time (<code>creopse install -t vue|react</code>) and shapes the rest of development (conventions, components). There&#39;s no automatic switch once the project is up and running — see <a href="./../development/template-structure.html">Template structure</a>.</p><h3 id="is-documentation-coverage-the-same-for-vue-and-react" tabindex="-1">Is documentation coverage the same for Vue and React? <a class="header-anchor" href="#is-documentation-coverage-the-same-for-vue-and-react" aria-label="Permalink to &quot;Is documentation coverage the same for Vue and React?&quot;">​</a></h3><p>Both stacks share the same API (<code>@creopse/utils</code>, the same composables/hooks named identically), but Vue patterns are backed by more real-world examples than React&#39;s at this stage — see <a href="./../development/sections-widgets.html">Sections &amp; Widgets</a>.</p><h2 id="miscellaneous" tabindex="-1">Miscellaneous <a class="header-anchor" href="#miscellaneous" aria-label="Permalink to &quot;Miscellaneous&quot;">​</a></h2><h3 id="where-are-all-the-available-cli-commands-documented" tabindex="-1">Where are all the available CLI commands documented? <a class="header-anchor" href="#where-are-all-the-available-cli-commands-documented" aria-label="Permalink to &quot;Where are all the available CLI commands documented?&quot;">​</a></h3><p>In the <a href="./cli.html">CLI reference</a>, which covers <code>section</code>, <code>widget</code>, <code>page</code>, <code>content-model</code>, <code>permalink</code>, <code>menu</code>, <code>media</code>, and <code>base-info</code>.</p><h3 id="how-do-i-update-creopse-to-a-newer-version" tabindex="-1">How do I update Creopse to a newer version? <a class="header-anchor" href="#how-do-i-update-creopse-to-a-newer-version" aria-label="Permalink to &quot;How do I update Creopse to a newer version?&quot;">​</a></h3><p>See <a href="./../development/updating-creopse.html">Updating Creopse</a>.</p>',35)])])}const u=a(s,[["render",i]]);export{p as __pageData,u as default};
